package com.argument.integration;

import com.argument.adjudication.SharedAdjudicationDependencies;
import com.argument.version.port.AnnotationDependencies;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

class RelationIntegrationSemanticsTest {
    final ObjectMapper mapper=new ObjectMapper();final StructureEngine engine=new StructureEngine();final AnnotationDependencies data=mock(AnnotationDependencies.class);
    ObjectNode element(String id,String owner,String display){return mapper.createObjectNode().put("id",id).put("ownerId",owner).put("isProposition",true).put("displayNo",display).put("labelCode","GM-L").put("text",id);}
    ObjectNode relation(String id,String owner,String code){return mapper.createObjectNode().put("id",id).put("ownerId",owner).put("ownerType","ANNOTATION_VERSION").put("relationCode",code).put("directed",Set.of("S","A","M").contains(code)).put("status","ACTIVE");}
    void part(ObjectNode snapshot,String relation,int ordinal,String role,String kind,String target){((ArrayNode)snapshot.get("participants")).addObject().put("id",relation+ordinal).put("relationId",relation).put("ordinal",ordinal).put("role",role).put("targetKind",kind).put("targetId",target);}
    ObjectNode snapshot(String version,boolean reverse){var s=mapper.createObjectNode();s.putObject("version").put("id",version);s.putArray("elements").add(element(version+"a",version,"P1")).add(element(version+"b",version,"P2"));s.putArray("relations").add(relation(version+"r",version,"S"));s.putArray("participants");part(s,version+"r",1,"SOURCE","ELEMENT",version+(reverse?"b":"a"));part(s,version+"r",2,"TARGET","ELEMENT",version+(reverse?"a":"b"));return s;}
    SharedAdjudicationDependencies dependencies(List<ObjectNode> snapshots,boolean sameMapping){var mapping=mapper.createObjectNode().put("id","session");var ids=mapping.putObject("elementMap");for(var s:snapshots){String v=s.path("version").path("id").asText();ids.put(v+"a",sameMapping?"ua":v+"ua");ids.put(v+"b",sameMapping?"ub":v+"ub");}when(data.read("adjudicationMapping","session")).thenReturn(mapping);return new SharedAdjudicationDependencies(data,mapper,null,engine);}
    @Test void threeSourcesProduceOneUniqueDirectionItem(){var sources=List.of(snapshot("v1",false),snapshot("v2",true),snapshot("v3",false));var result=dependencies(sources,true).compareRelations(mapper.createObjectNode().put("id","session"),sources);assertThat(result).hasSize(1);assertThat(result.get(0).path("conflictType").asText()).isEqualTo("DIRECTION");assertThat(result.get(0).path("candidateRelationIds")).hasSize(3);}
    @Test void sameDisplayNumbersAcrossVersionsCannotSubstituteForRealMapping(){var sources=List.of(snapshot("v1",false),snapshot("v2",false));var result=dependencies(sources,false).compareRelations(mapper.createObjectNode().put("id","session"),sources);assertThat(result).hasSize(2);assertThat(result).allMatch(i->"EXISTENCE".equals(i.path("conflictType").asText()));}
    @Test void nestedInnerDirectionRemainsPartOfOuterStructure(){var sources=List.of(snapshot("v1",false),snapshot("v2",true));for(var s:sources){String v=s.path("version").path("id").asText();((ArrayNode)s.get("elements")).add(element(v+"c",v,"P3"));((ArrayNode)s.get("relations")).add(relation(v+"outer",v,"S"));part(s,v+"outer",1,"SOURCE","RELATION",v+"r");part(s,v+"outer",2,"TARGET","ELEMENT",v+"c");}var deps=dependencies(sources,true);var mapping=data.read("adjudicationMapping","session");((ObjectNode)mapping.get("elementMap")).put("v1c","uc").put("v2c","uc");var result=deps.compareRelations(mapper.createObjectNode().put("id","session"),sources);assertThat(result).hasSize(2);assertThat(result).noneMatch(i->"AGREEMENT".equals(i.path("conflictType").asText()));}
    @Test void completeGraphContainsMultipleStructuresAndIsolatedProposition(){var elements=List.of(element("a","owner","P1"),element("b","owner","P2"),element("c","owner","P3"));var r=relation("r","owner","S");var s=mapper.createObjectNode();s.putArray("participants");part(s,"r",1,"SOURCE","ELEMENT","a");part(s,"r",2,"TARGET","ELEMENT","b");var ps=new ArrayList<ObjectNode>();s.path("participants").forEach(p->ps.add((ObjectNode)p));var result=engine.inspect("owner",elements,List.of(r),ps);assertThat(result.graph().nodes()).hasSize(4);assertThat(result.graph().componentCount()).isEqualTo(2);assertThat(result.graph().isolatedNodeIds()).containsExactly("c");assertThat(result.issues()).isEmpty();}
    @Test void deletingInnerRelationCannotLeaveAnAdoptedOuterReference(){
        var source=snapshot("v1",false);((ArrayNode)source.get("relations")).add(relation("outer","v1","S"));part(source,"outer",1,"SOURCE","RELATION","v1r");part(source,"outer",2,"TARGET","ELEMENT","v1a");var deps=dependencies(List.of(source),true);var mapping=data.read("adjudicationMapping","session");mapping.put("unifiedSnapshotId","u");var unified=mapper.createObjectNode().put("id","u");unified.putArray("elements").add(element("ua","u","P1")).add(element("ub","u","P2"));when(data.read("unifiedSnapshot","u")).thenReturn(unified);
        var inner=mapper.createObjectNode().put("id","inner").put("status","DECIDED").put("decisionId","delete");inner.putArray("candidateRelationIds").add("v1r");var outer=mapper.createObjectNode().put("id","outer-item").put("status","DECIDED").put("decisionId","adopt");outer.putArray("candidateRelationIds").add("outer");var delete=mapper.createObjectNode().put("id","delete").put("action","DELETE");var adopt=mapper.createObjectNode().put("id","adopt").put("action","ADOPT_VERSION").put("sourceObjectId","outer");assertThatThrownBy(()->deps.validateRelations(mapper.createObjectNode().put("id","session"),List.of(source),List.of(inner,outer),List.of(delete,adopt))).isInstanceOf(com.argument.common.exception.BusinessException.class).hasMessageContaining("内层关系");
    }

}
